return ['domain'=>'zinn-offload','plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'hi_IN','project-id-version'=>'zinn-offload','pot-creation-date'=>'2026-09-08T21:12:46+00:00','po-revision-date'=>'2026-09-08T21:12:46+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Media Offload'=>'Zinn® Media Offload','https://zinndigital.com/wordpress-plugins/zinn-offload'=>'https://zinndigital.com/wordpress-plugins/zinn-offload','Moves this site\'s media library to Zinn® object storage and serves it from a CDN. Configured from your Zinn® dashboard — no access key is ever typed into WordPress.'=>'इस साइट की मीडिया लाइब्रेरी को Zinn® ऑब्जेक्ट स्टोरेज में ले जाता है और इसे एक CDN से सर्व करता है। आपके Zinn® डैशबोर्ड से कॉन्फ़िगर किया गया — WordPress में कभी भी कोई एक्सेस की टाइप नहीं की जाती है।','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'सहेजा गया। इसे बदलने के लिए एक नया मान टाइप करें।','Filter this list…'=>'इस सूची को फ़िल्टर करें...','Filter this list'=>'इस सूची को फ़िल्टर करें','Nothing matches that filter.'=>'इस फ़िल्टर से कुछ भी मेल नहीं खाता।','Add a row'=>'एक पंक्ति जोड़ें','Remove this row'=>'इस पंक्ति को हटाएँ','Remove'=>'हटाएं','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — सिंहावलोकन','Overview'=>'अवलोकन','Every Zinn® plugin on this site, and whether it is working.'=>'इस साइट पर मौजूद हर Zinn® प्लगइन, और क्या यह काम कर रहा है।','No connection is needed for this plugin.'=>'इस प्लगइन के लिए किसी कनेक्शन की आवश्यकता नहीं है।','Open settings'=>'सेटिंग्स खोलें','You do not have permission to change these settings.'=>'आपको इन सेटिंग्स को बदलने की अनुमति नहीं है।','Settings sections'=>'सेटिंग्स अनुभाग','Support'=>'सहायता','Save changes'=>'परिवर्तन सहेजें','Tools'=>'टूल','Export settings'=>'निर्यात सेटिंग्स','Reset to defaults'=>'डिफ़ॉल्ट पर रीसेट करें','This puts every setting on this plugin back to its default. Continue?'=>'इससे इस प्लगइन की प्रत्येक सेटिंग अपने डिफ़ॉल्ट पर रीसेट हो जाती है। क्या आप जारी रखना चाहते हैं?','Diagnostics for support'=>'सहायता के लिए डायग्नोस्टिक्स','Import a settings file'=>'सेटिंग्स फ़ाइल आयात करें','Import'=>'आयात करें','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'निर्यात की गई फ़ाइलों में कभी भी पासवर्ड, टोकन या API कुंजियाँ (keys) नहीं होती हैं — आपको नए साइट पर उन्हें फिर से दर्ज करना होगा।','Settings saved.'=>'सेटिंग्स सहेजी गईं।','Every setting on this plugin is back to its default.'=>'इस प्लगइन की प्रत्येक सेटिंग वापस उसकी डिफ़ॉल्ट स्थिति में आ गई है।','Done.'=>'हो गया।','That action is not available.'=>'वह क्रिया उपलब्ध नहीं है।','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'वह फ़ाइल पढ़ी नहीं जा सकी। Zinn® प्लगइन से निर्यात की गई एक सेटिंग फ़ाइल चुनें।','That file is too large to be a settings export.'=>'वह फ़ाइल सेटिंग्स एक्सपोर्ट होने के लिए बहुत बड़ी है।','That file is not a Zinn® settings export.'=>'वह फ़ाइल Zinn® सेटिंग्स का निर्यात नहीं है।','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'वह फ़ाइल एक अलग प्लगइन (%s) से निर्यात की गई थी, इसलिए इसे यहाँ आयात करने से ऐसी सेटिंग्स संग्रहीत हो जाएँगी जिन्हें यह प्लगइन नहीं समझता है।','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d सेटिंग आयात की गई। पासवर्ड और API कुंजियाँ कभी भी निर्यात में शामिल नहीं होती हैं, इसलिए कृपया उन्हें दोबारा दर्ज करें।' . "\0" . '%d सेटिंग्स आयात की गईं। पासवर्ड और API कुंजियाँ कभी भी निर्यात में शामिल नहीं होती हैं, इसलिए उन्हें दोबारा दर्ज करें।','Zinn Digital® did not return a token. Nothing has been changed on this site.'=>'Zinn Digital® ने कोई टोकन नहीं लौटाया। इस साइट पर कुछ भी बदला नहीं गया है।','This site is no longer connected to Zinn® media offload. New uploads will stay on this server. Pair it again from your Zinn Digital® dashboard.'=>'यह साइट अब Zinn® मीडिया ऑफ़लोड से कनेक्टेड नहीं है। नए अपलोड्स इसी सर्वर पर रहेंगे। इसे अपने Zinn Digital® डैशबोर्ड से फिर से पेयर करें।','Zinn Digital® answered with HTTP %d.'=>'Zinn Digital® ने HTTP %d के साथ उत्तर दिया।','Disconnected by Zinn Digital®.'=>'Zinn Digital® द्वारा डिस्कनेक्ट किया गया।','Connected'=>'कनेक्टेड','Connecting…'=>'कनेक्ट हो रहा है...','Connected, but something needs attention'=>'कनेक्टेड है, लेकिन कुछ पर ध्यान देने की आवश्यकता है','Not connected'=>'कनेक्टेड नहीं है','Running on your own account'=>'अपने खाते पर चल रहा है','We could not check this'=>'हम इसकी जाँच नहीं कर सके','This plugin did not say why. Send a diagnostics report and we will look.'=>'इस प्लगइन ने कारण नहीं बताया। डायग्नोस्टिक्स रिपोर्ट भेजें और हम इसकी जाँच करेंगे।','Connection status'=>'कनेक्शन स्थिति','Last checked %s ago.'=>'अंतिम बार %s पहले जांचा गया था।','(opens in a new tab)'=>'(एक नए टैब में खुलता है)','Send this to Zinn® support'=>'Zinn® सपोर्ट को भेजें','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'ठीक यही भेजा जाएगा — इसके अलावा कुछ नहीं और कुछ भी छिपा हुआ नहीं है। इसमें आपके पासवर्ड, टोकन और API कुंजियाँ शामिल नहीं हैं।','The diagnostics report that will be sent'=>'निदान रिपोर्ट जो भेजी जाएगी','Copy to clipboard'=>'क्लिपबोर्ड पर कॉपी करें','Send this report to Zinn® support'=>'यह रिपोर्ट Zinn® सहायता को भेजें','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'हम आपके लिए एक सपोर्ट टिकट खोलते हैं और ईमेल द्वारा उत्तर देते हैं। यदि आप इसे भेजना नहीं चाहते हैं, तो इसे ऊपर से कॉपी करें और स्वयं किसी टिकट में पेस्ट करें।','Copied'=>'कॉपी किया गया','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'इस सर्वर (%s) से Zinn Digital® तक नहीं पहुँचा जा सका। ऊपर दी गई रिपोर्ट को कॉपी करें और इसके बजाय एक टिकट खोलें — आपकी सेटिंग में कुछ भी गलत नहीं है।','Sent. Zinn® support has your report and will reply by email.'=>'Zinn® सहायता टीम को आपकी रिपोर्ट मिल गई है और वह ईमेल के माध्यम से उत्तर देगी।','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Zinn® सहायता के पास आपकी रिपोर्ट है — संदर्भ %s — और वह ईमेल द्वारा उत्तर देगी।','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'आपने थोड़े ही समय में कई रिपोर्टें भेज दी हैं। कुछ मिनट प्रतीक्षा करें और पुनः प्रयास करें — पिछली रिपोर्टें प्राप्त हो चुकी हैं।','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® अभी इस रिपोर्ट को स्वीकार नहीं कर सका — यह हमारी तरफ से समस्या है, आपकी तरफ से नहीं। थोड़ी देर में पुनः प्रयास करें, या ऊपर दी गई रिपोर्ट को किसी टिकट में कॉपी करें।','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'रिपोर्ट अस्वीकार कर दी गई (HTTP %d)। इसे ऊपर से कॉपी करें और उस नंबर का हवाला देते हुए एक टिकट खोलें।','%s — guides and services'=>'%s — गाइड और सेवाएँ','User guides'=>'उपयोगकर्ता मार्गदर्शिकाएँ','Read the %s user guide'=>'%s उपयोगकर्ता गाइड पढ़ें','Hide this'=>'इसे छिपाएँ','Zinn® hosting for WordPress'=>'WordPress के लिए Zinn® होस्टिंग','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, दैनिक बैकअप, निःशुल्क माइग्रेशन और एक नियंत्रण कक्ष जिसे एक से अधिक साइटें चलाने वाले लोगों के लिए बनाया गया है।','The Zinn® marketplace'=>'Zinn® बाज़ार','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'स्थापित साइटों, डोमेन और लिंक प्लेसमेंट खरीदें और बेचें, और दोनों पक्षों के संतुष्ट होने तक पैसे सुरक्षित रखे जाते हैं।','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — ऐसे लोगों को काम पर रखें जो इसी पेशे में हैं','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'हमारा वैश्विक फ्रीलांस बाज़ार: लेखकों, डिज़ाइनरों, डेवलपर्स और SEO विशेषज्ञों की 10,000 से अधिक तैयार सेवाओं को ब्राउज़ करें, या कोई प्रोजेक्ट पोस्ट करें और उन्हें बोली लगाने दें।','Media Offload'=>'मीडिया ऑफ़लोड','Connection'=>'कनेक्शन','What gets moved'=>'क्या ले जाया जाता है','How media is served'=>'मीडिया कैसे परोसा जाता है','Move a batch now'=>'अभी एक बैच ले जाएं','Media already moved is never affected by a change here — its address does not change.'=>'यहाँ पहले से स्थानांतरित की गई मीडिया पर किसी बदलाव का कोई प्रभाव नहीं पड़ता — उसका पता नहीं बदलता।','New uploads'=>'नई अपलोड्स','Move new uploads to Zinn® storage as they arrive'=>'नए अपलोड्स के आने पर उन्हें Zinn® स्टोरेज पर ले जाएँ','Existing media'=>'मौजूदा मीडिया','Keep moving the media library that is already here'=>'यहाँ मौजूद मीडिया लाइब्रेरी को स्थानांतरित करते रहें','A few files an hour, in the background, picking up where it left off. Turning this off pauses it; nothing already moved comes back.'=>'प्रति घंटे कुछ फाइलें, पृष्ठभूमि में, वहीं से शुरू करते हुए जहाँ से छोड़ा था। इसे बंद करने से यह रुक जाता है; जो कुछ भी पहले ही ले जाया जा चुका है, वह वापस नहीं आता।','Files per hourly pass'=>'प्रति घंटा पास फ़ाइलें','Each attachment is several files and every one is a full upload. Raise this on a fast host with a generous execution limit; lower it if passes are being cut short.'=>'प्रत्येक अटैचमेंट कई फाइलें हैं और हर एक एक पूर्ण अपलोड है। इसे एक तेज़ होस्ट पर बढ़ाएं जिसकी निष्पादन सीमा उदार हो; यदि पास समय से पहले समाप्त हो रहे हैं तो इसे कम करें।','Leave files smaller than'=>'इससे छोटी फ़ाइलें छोड़ें','Kilobytes. A tiny icon costs more in the extra connection than it saves in disk, so there is rarely a reason to move one. Set to 0 to move everything.'=>'किलोबाइट। डिस्क पर बचने वाले स्थान की तुलना में एक छोटे आइकन की अतिरिक्त कनेक्शन लागत अधिक होती है, इसलिए इसे स्थानांतरित करने का शायद ही कोई कारण होता है। सब कुछ स्थानांतरित करने के लिए 0 पर सेट करें।','Never move these types'=>'इन प्रकारों को कभी न ले जाएँ','Useful when a plugin reads a file straight off the disk — a font, a PDF a form builder stamps, an audio file a player seeks inside.'=>'जब कोई प्लगइन सीधे डिस्क से कोई फ़ाइल पढ़ता है — जैसे कि कोई फ़ॉन्ट, कोई पीडीएफ़ जिस पर फ़ॉर्म बिल्डर मुहर लगाता है, या कोई ऑडियो फ़ाइल जिसके भीतर कोई प्लेयर खोजता है, तब यह उपयोगी होता है।','These two are the ones to be careful with — read each description before changing it.'=>'इन दोनों से सावधान रहने की ज़रूरत है — बदलने से पहले प्रत्येक विवरण को ध्यान से पढ़ें।','Serve from Zinn® storage'=>'Zinn® स्टोरेज से परोसें','Point image and file addresses at Zinn® storage'=>'पॉइंट इमेज और फ़ाइल पते Zinn® स्टोरेज पर इंगित करें','Off, files are uploaded but still served from this server — which is the safe state while you check everything arrived. On, visitors are served from storage and this server stops carrying the traffic.'=>'बंद है, फ़ाइलें अपलोड हो चुकी हैं लेकिन अभी भी इसी सर्वर से परोसी जा रही हैं — जो कि सब कुछ पहुँचने की जाँच करते समय सुरक्षित स्थिति है। चालू है, विज़िटर्स को स्टोरेज से सामग्री परोसी जाती है और यह सर्वर ट्रैफ़िक संभालना बंद कर देता है।','Free the disk space'=>'डिस्क स्थान खाली करें','Delete the local copy once every size has uploaded'=>'हर साइज़ अपलोड होने के बाद स्थानीय कॉपी हटा दें','This is the point of offloading, and it is also the irreversible half. Leave it off until “Serve from Zinn® storage” is on and you have checked your site — a local copy is the only thing that saves you if something was missed.'=>'यह ऑफ़लोडिंग का बिंदु है, और यह अपरिवर्तनीय आधा हिस्सा भी है। इसे तब तक बंद रखें जब तक कि “Serve from Zinn® storage” चालू न हो जाए और आपने अपनी साइट की जाँच नहीं कर ली हो — यदि कुछ छूट गया हो तो केवल स्थानीय प्रति (लोकल कॉपी) ही आपको बचा सकती है।','Deleting local copies cannot be undone from this screen. Take a backup first — the Zinn® Connector plugin can do that for you.'=>'स्थानीय प्रतियों को हटाना इस स्क्रीन से पूर्ववत् नहीं किया जा सकता। पहले बैकअप लें — Zinn® Connector प्लगइन आपके लिए यह कर सकता है।','This site is not connected to Zinn® storage yet, so there is nowhere to move media to.'=>'यह साइट अभी Zinn® स्टोरेज से जुड़ी नहीं है, इसलिए मीडिया को स्थानांतरित करने के लिए कोई जगह नहीं है।','%d attachment moved.'=>'%d संलग्नक स्थानांतरित किया गया।' . "\0" . '%d संलग्नक स्थानांतरित किए गए।','This site is not connected to Zinn® storage.'=>'यह साइट Zinn® स्टोरेज से जुड़ी नहीं है।','Nothing is wrong — it has simply not been paired yet. Media stays on this server until it is.'=>'कुछ भी गलत नहीं है — इसे अभी तक जोड़ा नहीं गया है। ऐसा होने तक मीडिया इसी सर्वर पर रहता है।','Connected, but the last upload failed.'=>'कनेक्टेड है, लेकिन पिछला अपलोड विफल हो गया।','Try a batch now'=>'अब एक बैच आज़माएं','Connected. Every attachment has been moved.'=>'कनेक्ट हो गया। प्रत्येक अटैचमेंट को ले जाया गया है।','Connected. %1$s of %2$s attachments still on this server.'=>'कनेक्टेड। %1$s में से %2$s अटैचमेंट अभी भी इस सर्वर पर हैं।','Moved so far'=>'अब तक स्थानांतरित','%1$s files, %2$s'=>'%1$s फ़ाइलें, %2$s','Still on this server'=>'इस सर्वर पर अभी भी है','%1$s of %2$s attachments'=>'%2$s में से %1$s अनुलग्नक','Served from'=>'यहाँ से परोसा गया','this server'=>'यह सर्वर','Connect this site'=>'इस साइट को कनेक्ट करें','Open your Zinn Digital® dashboard, go to Storage → Media offload, and press “Pair a site”. Paste the code below.'=>'अपने Zinn Digital® डैशबोर्ड को खोलें, Storage → Media offload पर जाएं, और “Pair a site” दबाएं। नीचे दिया गया कोड पेस्ट करें।','Pairing code'=>'पेयरिंग कोड','Disconnect this site'=>'इस साइट को डिस्कनेक्ट करें','New uploads will stay on this server. Media already moved keeps working — its address does not change.'=>'नई अपलोड्स इसी सर्वर पर रहेंगी। जो मीडिया पहले ही ले जाया जा चुका है, वह काम करता रहेगा — उसका पता नहीं बदलता।','You do not have permission to manage this site.'=>'आपको इस साइट को प्रबंधित करने की अनुमति नहीं है।','Paste the pairing code from your Zinn Digital® dashboard.'=>'अपने Zinn Digital® डैशबोर्ड से पेयरिंग कोड पेस्ट करें।','Connected. New uploads will be stored with Zinn Digital® from now on, and your existing media will move in the background.'=>'कनेक्ट किया गया। अब से नए अपलोड Zinn Digital® के साथ संग्रहीत किए जाएंगे, और आपका मौजूदा मीडिया बैकग्राउंड में स्थानांतरित कर दिया जाएगा।','Disconnected. Media already moved keeps working; new uploads stay on this server.'=>'डिस्कनेक्ट हो गया। पहले से मूव की गई मीडिया काम करती रहेगी; नई अपलोड्स इस सर्वर पर रहेंगी।','That file could not be read from this server, so nothing was uploaded.'=>'इस सर्वर से उस फ़ाइल को पढ़ा नहीं जा सका, इसलिए कुछ भी अपलोड नहीं किया गया।','This site could not stream the upload, so nothing was sent.'=>'यह साइट अपलोड को स्ट्रीम नहीं कर सकी, इसलिए कुछ भी नहीं भेजा गया।','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'यह फ़ाइल %1$s है और इस साइट के PHP में cURL नहीं है, इसलिए यह ज़्यादा से ज़्यादा %2$s अपलोड कर सकती है।','The upload could not be completed.'=>'अपलोड पूरा नहीं किया जा सका।','Storage refused the upload (HTTP %d).'=>'भंडारण ने अपलोड अस्वीकार कर दिया (HTTP %d)।','Style preset'=>'शौक पूर्वसेट','A starting point. Anything below overrides it.'=>'एक शुरुआती बिंदु। इसके नीचे की कोई भी चीज़ इसे बदल देगी।','Use my own colours and sizes'=>'मेरे अपने रंगों और आकारों का उपयोग करें','Leave this off and the preset is used exactly as it is.'=>'इसे बंद रखें और प्रीसेट का उपयोग वैसे ही किया जाता है जैसे वह है।','See the Zinn Digital® release notes.'=>'Zinn Digital® रिलीज़ नोट्स देखें।','The downloaded update failed its integrity check and was not installed.'=>'डाउनलोड किए गए अपडेट की इंटीग्रिटी जाँच विफल हो गई और इसे स्थापित नहीं किया गया।']];